    /**
     * Method to retrieve the Goal via GoalFetchOneSummary
     * @param 	summary GoalFetchOneSummary 
     * @return 	GoalFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Goal getGoal( GoalFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "GoalFetchOneSummary arg cannot be null" );
    	
    	Goal entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Goal
        	// --------------------------------------
        	CompletableFuture<Goal> futureEntity = queryGateway.query(new FindGoalQuery( new LoadGoalFilter( summary.getGoalId() ) ), ResponseTypes.instanceOf(Goal.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Goal with id " + summary.getGoalId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


